// @ts-check
const { test, expect } = require('@playwright/test');

const SERVER_BASE_URL = (process.env.RDF4J_SERVER_BASE_URL || 'http://127.0.0.1:8090/rdf4j-server').replace(/\/+$/, '');
const WORKBENCH_BASE_URL = (process.env.RDF4J_WORKBENCH_BASE_URL || 'http://127.0.0.1:8090/rdf4j-workbench').replace(/\/+$/, '');
const REPOSITORY_ID = `workbench-disclosure-collapse-${process.pid}-${Date.now()}`;
const REPOSITORY_URL = `${SERVER_BASE_URL}/repositories/${REPOSITORY_ID}`;

test.beforeAll(async ({ request }) => {
	const created = await request.put(REPOSITORY_URL, {
		headers: { 'Content-Type': 'text/turtle' },
		data: repositoryConfiguration(REPOSITORY_ID)
	});
	expect([200, 201, 204]).toContain(created.status());
	const loaded = await request.post(`${REPOSITORY_URL}/statements`, {
		headers: { 'Content-Type': 'application/n-quads' },
		data: '<urn:motion:subject> <urn:motion:predicate> "value" .'
	});
	expect([200, 201, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
	const removed = await request.delete(REPOSITORY_URL);
	expect([200, 204, 404]).toContain(removed.status());
});

test('disclosure panels finish closing without a final panel or enclosing-layout jump', async ({ page }) => {
	test.setTimeout(180_000);
	await page.emulateMedia({ reducedMotion: 'no-preference' });
	for (const width of [1440, 390]) {
		await page.setViewportSize({ width, height: 1000 });
		await openPage(page, `repositories/${REPOSITORY_ID}/query`);
		await page.locator('.CodeMirror').first().evaluate(element =>
			element.CodeMirror.setValue('SELECT ?s WHERE { ?s ?p ?o }'));
		await page.locator('#exec').click();
		await expect(page.locator('#query-results-frame')).toBeVisible();
		const initialResultFrame = page.frame({ name: 'query-results-frame' });
		if (!initialResultFrame) {
			throw new Error('The query results iframe did not initialize');
		}
		await expect(initialResultFrame.locator('table.data tbody tr')).toHaveCount(1);
		await page.locator('#explain-trigger').click();
		await waitForExplanation(page);
		await assertCollapseContinuity(page, {
			name: `query Config ${width}px`,
			trigger: '#explanation-settings-toggle',
			animated: '#explanation-settings-panel',
			container: '.query-explanation-toolbar',
			containerEdge: 'bottom',
			downstream: '#query-results',
			downstreamEdge: 'top',
			closed: '#explanation-settings-panel[hidden]'
		});
		await assertCollapseContinuity(page, {
			name: `query Options ${width}px`,
			trigger: '#query-options-toggle',
			animated: '#query-options-panel',
			container: '.query-actions-toolbar',
			containerEdge: 'bottom',
			downstream: '#query-results',
			downstreamEdge: 'top',
			closed: '#query-options-panel[hidden]'
		});

		await openPage(page, `repositories/${REPOSITORY_ID}/query`);
		await page.locator('.CodeMirror').first().evaluate(element =>
			element.CodeMirror.setValue('SELECT ?s WHERE { VALUES ?s { "one" "two" } }'));
		await page.locator('#exec').click();
		await expect(page.locator('#query-results-frame')).toBeVisible();
		const resultFrame = page.frame({ name: 'query-results-frame' });
		if (!resultFrame) {
			throw new Error('The query results iframe did not initialize');
		}
		await expect(resultFrame.locator('table.data tbody tr')).toHaveCount(2);
		await assertCollapseContinuity(resultFrame, {
			name: `result iframe Options ${width}px`,
			trigger: '#query-result-options-toggle',
			animated: '#query-result-options-panel',
			container: 'body',
			containerEdge: 'bottom',
			assertContainer: false,
			outerContext: page,
			outerSelector: '#query-results-frame',
			outerEdge: 'bottom',
			downstream: '#query-result-layout',
			downstreamEdge: 'top',
			closed: '#query-result-options-panel[hidden]'
		});

		await openPage(page, `repositories/${REPOSITORY_ID}/add`);
		await assertCollapseContinuity(page, {
			name: `Add Advanced ${width}px`,
			trigger: '#add-import-settings > summary',
			animated: '#add-import-settings',
			container: '#workbench-page-surface',
			containerEdge: 'bottom',
			closed: '#add-import-settings:not([open])',
			native: true
		});

		await openPage(page, 'repositories/NONE/create?type=memory-customrule');
		await assertCollapseContinuity(page, {
			name: `Create Advanced ${width}px`,
			trigger: 'details.workbench-advanced > summary',
			animated: 'details.workbench-advanced',
			container: 'form[action="create"]',
			containerEdge: 'bottom',
			closed: 'details.workbench-advanced:not([open])',
			native: true
		});
	}
});

test('query option panels remain visually continuous and reverse from their current box styles', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 1000 });
	await page.emulateMedia({ reducedMotion: 'no-preference' });
	await openPage(page, `repositories/${REPOSITORY_ID}/query`);
	const toggle = page.locator('#query-options-toggle');
	const panel = page.locator('#query-options-panel');
	await toggle.click();
	await expect(panel).toBeVisible();
	await expect.poll(() => runningMotionCount(panel)).toBe(0);

	await page.evaluate(() => {
		const target = document.getElementById('query-options-panel');
		const anyWindow = /** @type {any} */ (window);
		const originalAnimate = Element.prototype.animate;
		anyWindow.workbenchCollapseTestHook = { target, animations: [], originalAnimate };
		Element.prototype.animate = function(keyframes, options) {
			const animation = originalAnimate.call(this, keyframes, options);
			const hook = /** @type {any} */ (window).workbenchCollapseTestHook;
			if (this === hook.target) {
				animation.pause();
				hook.animations.push(animation);
			}
			return animation;
		};
	});
	await toggle.click();
	await expect.poll(() => page.evaluate(() =>
		(/** @type {any} */ (window)).workbenchCollapseTestHook.animations.length)).toBe(1);
	const closeFrame = await page.evaluate(() => {
		const hook = (/** @type {any} */ (window)).workbenchCollapseTestHook;
		const animation = hook.animations[0];
		const panel = hook.target;
		const startHeight = panel.getBoundingClientRect().height;
		const duration = Number(animation.effect.getTiming().duration);
		animation.currentTime = duration * 0.25;
		const bounds = panel.getBoundingClientRect();
		const style = getComputedStyle(panel);
		const matrix = new DOMMatrixReadOnly(style.transform);
		return {
			startHeight,
			elapsed: animation.currentTime,
			duration,
			height: bounds.height,
			visible: bounds.height > 0 && style.visibility !== 'hidden',
			scaleY: matrix.d,
			heightStyle: style.height
		};
	});
	console.log(`DISCLOSURE_CLOSE_MIDFRAME ${JSON.stringify(closeFrame)}`);
	expect.soft(closeFrame.visible).toBe(true);
	expect.soft(closeFrame.height).toBeGreaterThan(closeFrame.startHeight * 0.25);
	expect.soft(closeFrame.scaleY).toBeGreaterThan(0.95);

	const reversal = await page.evaluate(() => {
		const hook = (/** @type {any} */ (window)).workbenchCollapseTestHook;
		const closing = hook.animations[0];
		const panel = hook.target;
		closing.currentTime = Number(closing.effect.getTiming().duration) * 0.5;
		const style = getComputedStyle(panel);
		const currentBox = {
			height: panel.getBoundingClientRect().height,
			paddingTop: style.paddingTop,
			paddingBottom: style.paddingBottom,
			borderTopWidth: style.borderTopWidth,
			borderBottomWidth: style.borderBottomWidth,
			marginBlockStart: style.marginBlockStart,
			marginBlockEnd: style.marginBlockEnd
		};
		document.getElementById('query-options-toggle').click();
		const opening = hook.animations[1];
		return {
			currentBox,
			openFirstFrame: opening.effect.getKeyframes()[0]
		};
	});
	console.log(`DISCLOSURE_REVERSE_FIRST_FRAME ${JSON.stringify(reversal)}`);
	await expect(toggle).toHaveAttribute('aria-expanded', 'true');
	await expect(panel).toHaveAttribute('aria-hidden', 'false');
	await expect.poll(() => panel.evaluate(element => element.inert)).toBe(false);
	for (const property of ['paddingTop', 'paddingBottom', 'borderTopWidth', 'borderBottomWidth',
		'marginBlockStart', 'marginBlockEnd']) {
		expect(reversal.openFirstFrame[property], property).toBe(reversal.currentBox[property]);
	}
});

test('Create Advanced reaches its natural closed box without a final frame jump', async ({ page }) => {
	await page.emulateMedia({ reducedMotion: 'no-preference' });
	for (const width of [1440, 390]) {
		await page.setViewportSize({ width, height: 1000 });
		await openPage(page, 'repositories/NONE/create?type=memory-customrule');
		const details = page.locator('details.workbench-advanced');
		const summary = details.locator(':scope > summary');
		await summary.press('Enter');
		await expect(details).toHaveAttribute('open', '');
		await page.evaluate(() => {
			const trace = { samples: [], complete: false };
			const anyWindow = /** @type {any} */ (window);
			anyWindow.nativeDisclosureTrace = trace;
			const details = document.querySelector('details.workbench-advanced');
			const form = document.querySelector('form[action="create"]');
			const sample = () => {
				const box = details.getBoundingClientRect();
				trace.samples.push({
					open: details.open,
					height: box.height,
					formBottom: form.getBoundingClientRect().bottom
				});
				if (details.open) {
					requestAnimationFrame(sample);
				} else {
					requestAnimationFrame(() => {
						const settledBox = details.getBoundingClientRect();
						trace.samples.push({
							open: details.open,
							height: settledBox.height,
							formBottom: form.getBoundingClientRect().bottom
						});
						trace.complete = true;
					});
				}
			};
			requestAnimationFrame(sample);
		});
		await summary.press('Enter');
		await expect(details).not.toHaveAttribute('open', '');
		await page.waitForFunction(() => (/** @type {any} */ (window)).nativeDisclosureTrace.complete);
		const trace = await page.evaluate(() => (/** @type {any} */ (window)).nativeDisclosureTrace.samples);
		const closedIndex = trace.findIndex(sample => !sample.open);
		const previous = trace[closedIndex - 1];
		const firstClosed = trace[closedIndex];
		const settled = trace[trace.length - 1];
		const finalPanelStep = Math.abs(previous.height - firstClosed.height);
		const finalFormStep = Math.abs(previous.formBottom - firstClosed.formBottom);
		console.log(`NATIVE_DISCLOSURE_FINAL_FRAME ${JSON.stringify({
			width,
			previous,
			firstClosed,
			settled,
			finalPanelStep,
			finalFormStep
		})}`);
		expect(finalPanelStep).toBeLessThanOrEqual(1);
		expect(finalFormStep).toBeLessThanOrEqual(1);
		expect(Math.abs(firstClosed.height - settled.height)).toBeLessThanOrEqual(0.1);
		expect(Math.abs(firstClosed.formBottom - settled.formBottom)).toBeLessThanOrEqual(0.1);
	}
});

async function assertCollapseContinuity(context, configuration) {
	const toggle = context.locator(configuration.trigger);
	const animated = context.locator(configuration.animated);
	await toggle.click();
	if (configuration.native) {
		await expect(animated).toHaveAttribute('open', '');
	} else {
		await expect(animated).toBeVisible();
	}
	await expect.poll(() => runningMotionCount(animated)).toBe(0);
	await context.evaluate(target => {
		const anyWindow = /** @type {any} */ (window);
		if (!anyWindow.workbenchMotionTestHook) {
			const originalAnimate = Element.prototype.animate;
			anyWindow.workbenchMotionTestHook = { target: null, animation: null, originalAnimate };
			Element.prototype.animate = function(keyframes, options) {
				const animation = originalAnimate.call(this, keyframes, options);
				const hook = /** @type {any} */ (window).workbenchMotionTestHook;
				if (hook.target && this.matches(hook.target)) {
					hook.animation = animation;
					animation.pause();
				}
				return animation;
			};
		}
		anyWindow.workbenchMotionTestHook.target = target;
		anyWindow.workbenchMotionTestHook.animation = null;
	}, configuration.animated);
	await toggle.click();
	await expect.poll(() => context.evaluate(() =>
		Boolean((/** @type {any} */ (window)).workbenchMotionTestHook.animation))).toBe(true);
	const beforeFinish = await context.evaluate(async ({ animatedSelector, containerSelector, edge,
			downstreamSelector, downstreamEdge }) => {
		const anyWindow = /** @type {any} */ (window);
		const animation = anyWindow.workbenchMotionTestHook.animation;
		const duration = Number(animation.effect.getTiming().duration);
		const panel = document.querySelector(animatedSelector);
		const nearEndSamples = [150, 170, 179, 179.9, duration - 0.001].map(time => {
			animation.currentTime = Math.min(time, duration - 0.001);
			const style = getComputedStyle(panel);
			return {
				time: animation.currentTime,
				progress: animation.effect.getComputedTiming().progress,
				height: panel.getBoundingClientRect().height,
				borderTop: style.borderTopWidth,
				borderBottom: style.borderBottomWidth,
				paddingTop: style.paddingTop
			};
		});
		animation.currentTime = Math.max(0, duration - 0.001);
		await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
		const container = document.querySelector(containerSelector);
		const downstream = downstreamSelector ? document.querySelector(downstreamSelector) : null;
		const embedded = document.getElementById('query-result-embedded');
		const panelRect = panel.getBoundingClientRect();
		const containerRect = container.getBoundingClientRect();
		const styles = getComputedStyle(panel);
		const track = panel.parentElement;
		const trackRect = track.getBoundingClientRect();
		const trackStyle = getComputedStyle(track);
		return {
			panelHeight: panelRect.height,
			panelBottom: panelRect.bottom,
			containerHeight: containerRect.height,
			containerEdge: containerRect[edge],
			downstreamEdge: downstream ? downstream.getBoundingClientRect()[downstreamEdge] : null,
			trackHeight: trackRect.height,
			trackRows: trackStyle.gridTemplateRows,
			panelMinHeight: styles.minHeight,
			panelScrollHeight: panel.scrollHeight,
			embeddedHeight: embedded ? embedded.getBoundingClientRect().height : null,
			embeddedScrollHeight: embedded ? embedded.scrollHeight : null,
			documentHeight: document.documentElement.scrollHeight,
			bodyScrollHeight: document.body.scrollHeight,
			animationEndHeight: animation.effect.getKeyframes().slice(-1)[0].height,
			animationEndBorderTop: animation.effect.getKeyframes().slice(-1)[0].borderTopWidth,
			animationEndBorderBottom: animation.effect.getKeyframes().slice(-1)[0].borderBottomWidth,
			nearEndSamples,
			paddingTop: styles.paddingTop,
			paddingBottom: styles.paddingBottom,
			borderTop: styles.borderTopWidth,
			borderBottom: styles.borderBottomWidth,
			marginBottom: styles.marginBottom,
			rowGap: styles.rowGap,
			animationDuration: duration,
			animationTime: animation.currentTime
		};
	}, {
		animatedSelector: configuration.animated,
		containerSelector: configuration.container,
		edge: configuration.containerEdge,
		downstreamSelector: configuration.downstream,
		downstreamEdge: configuration.downstreamEdge
	});
	const outerBeforeFinish = configuration.outerSelector
		? await geometryAt(configuration.outerContext, configuration.outerSelector, configuration.outerEdge)
		: null;
	await context.evaluate(() => (/** @type {any} */ (window)).workbenchMotionTestHook.animation.finish());
	if (configuration.native) {
		await expect(context.locator(configuration.closed)).toBeVisible();
	} else {
		await expect(context.locator(configuration.closed)).toBeHidden();
	}
	await expect.poll(() => runningMotionCount(animated)).toBe(0);
	await context.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
	const afterFinish = await context.evaluate(({ animatedSelector, containerSelector, edge,
			downstreamSelector, downstreamEdge }) => {
		const panel = document.querySelector(animatedSelector);
		const panelRect = panel.getBoundingClientRect();
		const containerRect = document.querySelector(containerSelector).getBoundingClientRect();
		const panelStyle = getComputedStyle(panel);
		const trackRect = panel.parentElement.getBoundingClientRect();
		const trackStyle = getComputedStyle(panel.parentElement);
		const summary = panel.querySelector(':scope > summary');
		const summaryHeight = summary ? summary.getBoundingClientRect().height : null;
		const downstream = downstreamSelector ? document.querySelector(downstreamSelector) : null;
		return {
			panelHeight: panelRect.height,
			panelBottom: panelRect.bottom,
			panelHidden: panel.hidden,
			panelDisplay: panelStyle.display,
			panelHeightStyle: panelStyle.height,
			trackHeight: trackRect.height,
			trackRows: trackStyle.gridTemplateRows,
			panelMinHeight: panelStyle.minHeight,
			panelScrollHeight: panel.scrollHeight,
			summaryHeight,
			containerHeight: containerRect.height,
			containerEdge: containerRect[edge],
			downstreamEdge: downstream ? downstream.getBoundingClientRect()[downstreamEdge] : null
		};
	}, {
		animatedSelector: configuration.animated,
		containerSelector: configuration.container,
		edge: configuration.containerEdge,
		downstreamSelector: configuration.downstream,
		downstreamEdge: configuration.downstreamEdge
	});
	const outerAfterFinish = configuration.outerSelector
		? await geometryAt(configuration.outerContext, configuration.outerSelector, configuration.outerEdge)
		: null;
	console.log(`DISCLOSURE_COLLAPSE_GEOMETRY ${JSON.stringify({
		name: configuration.name,
		beforeFinish,
		afterFinish,
		outerBeforeFinish,
		outerAfterFinish,
		panelHeightJump: Math.abs(beforeFinish.panelHeight - afterFinish.panelHeight),
		containerHeightJump: Math.abs(beforeFinish.containerHeight - afterFinish.containerHeight),
		containerEdgeJump: Math.abs(beforeFinish.containerEdge - afterFinish.containerEdge),
		outerEdgeJump: outerBeforeFinish ? Math.abs(outerBeforeFinish.edge - outerAfterFinish.edge) : null,
		downstreamEdgeJump: beforeFinish.downstreamEdge === null ? null
			: Math.abs(beforeFinish.downstreamEdge - afterFinish.downstreamEdge)
	})}`);
	expect.soft(Math.abs(beforeFinish.panelHeight - afterFinish.panelHeight), configuration.name).toBeLessThanOrEqual(1);
	if (configuration.assertContainer !== false) {
		expect.soft(Math.abs(beforeFinish.containerHeight - afterFinish.containerHeight), configuration.name)
			.toBeLessThanOrEqual(1);
		expect.soft(Math.abs(beforeFinish.containerEdge - afterFinish.containerEdge), configuration.name)
			.toBeLessThanOrEqual(1);
	}
	if (beforeFinish.downstreamEdge !== null) {
		expect.soft(Math.abs(beforeFinish.downstreamEdge - afterFinish.downstreamEdge), configuration.name)
			.toBeLessThanOrEqual(1);
	}
	if (outerBeforeFinish) {
		expect.soft(Math.abs(outerBeforeFinish.edge - outerAfterFinish.edge), configuration.name)
			.toBeLessThanOrEqual(1);
	}
	await context.evaluate(() => {
		const hook = (/** @type {any} */ (window)).workbenchMotionTestHook;
		hook.target = null;
	});
}

async function geometryAt(context, selector, edge) {
	return context.locator(selector).evaluate((element, measuredEdge) => {
		const bounds = element.getBoundingClientRect();
		return { height: bounds.height, edge: bounds[measuredEdge] };
	}, edge);
}

async function runningMotionCount(locator) {
	return locator.evaluate(element => element.getAnimations({ subtree: false })
		.filter(animation => animation.playState === 'running').length);
}

async function openPage(page, route) {
	await page.goto(`${WORKBENCH_BASE_URL}/${route}`, { waitUntil: 'load' });
	await page.locator('#workbench-page-surface').waitFor({ state: 'visible', timeout: 15_000 });
	await page.evaluate(() => document.fonts.ready);
}

async function waitForExplanation(page) {
	await page.waitForFunction(() => {
		const explanation = document.querySelector('#query-explanation');
		const status = document.querySelector('#query-explanation-status');
		return explanation && explanation.textContent.trim().length > 0
			&& !(status && /loading/i.test(status.textContent));
	});
	await expect(page.locator('.query-explanation-overlay--visible')).toHaveCount(0);
}

function repositoryConfiguration(repositoryId) {
	return `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>.
@prefix config: <tag:rdf4j.org,2023:config/>.
[] a config:Repository ; config:rep.id "${repositoryId}" ; rdfs:label "Disclosure collapse geometry fixture" ;
   config:rep.impl [ config:rep.type "openrdf:SailRepository" ;
      config:sail.impl [ config:sail.type "openrdf:MemoryStore" ] ].`;
}
